import { useContext, useState, useEffect } from "react";
import { AuthContext } from "../context/AuthContext";
import { useNavigate } from "react-router-dom";
import api from "../api";

export default function AdminDashboard() {
  const { logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);

  // Fetch initial data
  useEffect(() => {
    fetchVotingStatus();
    fetchPendingUsers();
    fetchCandidates();
    fetchLogs();
  }, []);

  // ------------------
  // Handlers
  // ------------------
  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  const fetchVotingStatus = async () => {
    // Example endpoint, replace with your API
    const res = await api.get("/admin/voting-status");
    setVotingOpen(res.data.votingOpen);
  };

  const toggleVoting = async () => {
    const res = await api.post("/admin/toggle-voting");
    setVotingOpen(res.data.votingOpen);
    // Optionally log action
  };

  const fetchPendingUsers = async () => {
    const res = await api.get("/admin/pending-users");
    setPendingUsers(res.data);
  };

  const approveUser = async (id) => {
    await api.post(`/admin/approve-user/${id}`);
    fetchPendingUsers();
  };

  const fetchCandidates = async () => {
    const res = await api.get("/admin/candidates");
    setCandidates(res.data);
  };

  const addCandidate = async () => {
    // Redirect to candidate form or open modal
    navigate("/admin/add-candidate");
  };

  const fetchLogs = async () => {
    const res = await api.get("/admin/logs");
    setLogs(res.data);
  };

  const generateReport = async () => {
    const res = await api.post("/admin/generate-report");
    alert("Report generated ✅");
    // Optionally download or show report
  };

  return (
    <div className="min-h-screen p-6 bg-gray-50">
      {/* Header */}
      <header className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-gray-800">iVote Admin Dashboard</h1>
        <button
          onClick={handleLogout}
          className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700 transition"
        >
          Logout
        </button>
      </header>

      {/* Voting Status */}
      <section className="mb-6 p-4 bg-white rounded shadow">
        <h2 className="text-xl font-semibold mb-2">Voting Status</h2>
        <p>Current Status: {votingOpen ? "Open" : "Closed"}</p>
        <button
          onClick={toggleVoting}
          className={`mt-2 px-4 py-2 rounded text-white ${
            votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"
          } transition`}
        >
          {votingOpen ? "Close Voting" : "Open Voting"}
        </button>
      </section>

      {/* Pending Users */}
      <section className="mb-6 p-4 bg-white rounded shadow">
        <h2 className="text-xl font-semibold mb-2">Pending Voter Registrations</h2>
        {pendingUsers.length === 0 ? (
          <p>No pending users.</p>
        ) : (
          <ul>
            {pendingUsers.map((user) => (
              <li key={user.id} className="flex justify-between mb-1">
                {user.name} ({user.studentNumber})
                <button
                  onClick={() => approveUser(user.id)}
                  className="text-green-600 hover:underline"
                >
                  Approve
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      {/* Candidates */}
      <section className="mb-6 p-4 bg-white rounded shadow">
        <h2 className="text-xl font-semibold mb-2">Candidates</h2>
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b">
              <th className="py-2">Name</th>
              <th className="py-2">Position</th>
              <th className="py-2">Party</th>
              <th className="py-2">Actions</th>
            </tr>
          </thead>
          <tbody>
            {candidates.length === 0 ? (
              <tr>
                <td colSpan="4" className="py-2 text-center text-gray-500">
                  No candidates yet.
                </td>
              </tr>
            ) : (
              candidates.map((c) => (
                <tr key={c.id} className="border-b">
                  <td className="py-2">{c.name}</td>
                  <td className="py-2">{c.position}</td>
                  <td className="py-2">{c.party || "-"}</td>
                  <td className="py-2">
                    <button className="text-blue-600 hover:underline mr-2">Edit</button>
                    <button className="text-red-600 hover:underline">Delete</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
        <button
          onClick={addCandidate}
          className="mt-2 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition"
        >
          Add Candidate
        </button>
      </section>

      {/* System Logs */}
      <section className="mb-6 p-4 bg-white rounded shadow">
        <h2 className="text-xl font-semibold mb-2">System Logs</h2>
        {logs.length === 0 ? (
          <p>No logs available.</p>
        ) : (
          <ul className="text-sm">
            {logs.map((log, idx) => (
              <li key={idx}>{log}</li>
            ))}
          </ul>
        )}
      </section>

      {/* Reports */}
      <section className="mb-6 p-4 bg-white rounded shadow">
        <h2 className="text-xl font-semibold mb-2">Reports</h2>
        <button
          onClick={generateReport}
          className="bg-purple-600 text-white px-4 py-2 rounded hover:bg-purple-700 transition"
        >
          Generate Final Report
        </button>
      </section>
    </div>
  );
}
